type SecondParameter<T extends (...args: never) => unknown> = Parameters<T>[1];

/**
 * @summary Загрузить выписку (CSV, XLSX, 1С ClientBankExchange), асинхронно
 */
export const getCreateImportUrl = (companyId: string) => {
  return `/api/v1/ledger/companies/${companyId}/imports`;
};

export const createImport = async (
  companyId: string,
  createImportBody: CreateImportBody,
  options?: RequestInit,
): Promise<Import> => {
  const formData = new FormData();
  formData.append(`file`, createImportBody.file);
  if (createImportBody.mappingId !== undefined) {
    formData.append(`mappingId`, createImportBody.mappingId);
  }
  if (createImportBody.mapping !== undefined) {
    formData.append(`mapping`, JSON.stringify(createImportBody.mapping));
  }

  return http<Import>(getCreateImportUrl(companyId), {
    ...options,
    method: "POST",
    body: formData,
  });
};

export const getCreateImportMutationOptions = <
  TError = UnprocessableResponse | TooManyResponse,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createImport>>,
    TError,
    { companyId: string; data: CreateImportBody },
    TContext
  >;
  request?: SecondParameter<typeof http>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createImport>>,
  TError,
  { companyId: string; data: CreateImportBody },
  TContext
> => {
  const mutationKey = ["createImport"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createImport>>,
    { companyId: string; data: CreateImportBody }
  > = (props) => {
    const { companyId, data } = props ?? {};

    return createImport(companyId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CreateImportMutationResult = NonNullable<Awaited<ReturnType<typeof createImport>>>;
export type CreateImportMutationBody = CreateImportBody;
export type CreateImportMutationError = UnprocessableResponse | TooManyResponse;

